{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Risedronate, a 3-pyridylmethyl-containing bisphosphonate, has absolute oral bioavailability <0.5% in humans; this is the only direct low-F evidence, but its very low absorption is attributable to the bisphosphonate moiety rather than the shared pyridylmethyl fragment.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Amrinone, an aminopyridinone with a pyridyl substituent, shows 90-95% oral bioavailability in healthy subjects, supporting high F for the similarly polar aminopyrimidinone/pyridylmethyl query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Aminophylline/theophylline, a purine (xanthine) closely related to the guanine core, has 94% bioavailability relative to IV, supporting high oral F for the purine-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Enprofylline, another xanthine, has 94% absolute oral bioavailability, reinforcing that purine-type scaffolds with oxo groups can be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Nicorandil, a 3-pyridyl-containing drug, has absolute oral bioavailability of 79±9% in healthy volunteers, showing that pyridine-containing polar molecules can achieve high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Norzimelidine, which contains a 3-pyridyl group, has mean oral bioavailability of 66% in healthy volunteers, supporting high F for the query's pyridylmethyl-substituted heteroaromatic.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Vonoprazan, a pyridine-containing heteroaromatic, has estimated human oral bioavailability of 36%, still above the 20% threshold and supportive of high classification.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a polar guanine-like purine with a 3-pyridylmethyl substituent. Most transferable experimental evidence from pyridine-containing and purine/xanthine analogues shows oral bioavailability well above 20% (amrinone 90-95%, theophylline/enprofylline 94%, nicorandil 75-100%, norzimelidine 66%, vonoprazan 36%). The only low-F analogue, risedronate, owes its <1% F to bisphosphonate polarity and is poorly transferable. Therefore predict high.",
  "evidence_gaps": [
    "No direct human oral bioavailability measurement for the exact query molecule.",
    "Morgan similarities to available evidence are low, limiting quantitative transferability.",
    "No data on solubility, permeability, or efflux for this specific guanine derivative.",
    "The low-F risedronate evidence is mechanistically dominated by bisphosphonate chemistry not present in the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

